CREATE TABLE IF NOT EXISTS agencia(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(100) NOT NULL,ciudad VARCHAR(80) NOT NULL,direccion VARCHAR(180),telefono VARCHAR(20),activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS empleado(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,agencia_id BIGINT NOT NULL REFERENCES agencia(id),nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,documento VARCHAR(15) NOT NULL UNIQUE,cargo VARCHAR(30) NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS pasajero(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tipo_documento VARCHAR(12) NOT NULL CHECK(tipo_documento IN ('DNI','CE','PASAPORTE')),documento VARCHAR(15) NOT NULL,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,telefono VARCHAR(20),correo VARCHAR(120),fecha_registro TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tipo_documento,documento));
CREATE TABLE IF NOT EXISTS ruta(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,origen VARCHAR(80) NOT NULL,destino VARCHAR(80) NOT NULL,distancia_km DECIMAL(8,2) NOT NULL CHECK(distancia_km>0),duracion_min INTEGER NOT NULL CHECK(duracion_min>0),activo BOOLEAN NOT NULL DEFAULT TRUE,CHECK(origen<>destino));
CREATE TABLE IF NOT EXISTS bus(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,placa VARCHAR(12) NOT NULL UNIQUE,marca VARCHAR(60) NOT NULL,modelo VARCHAR(60),capacidad INTEGER NOT NULL CHECK(capacidad BETWEEN 1 AND 60),soat_hasta DATE NOT NULL,revision_hasta DATE NOT NULL,estado VARCHAR(20) NOT NULL CHECK(estado IN ('OPERATIVO','MANTENIMIENTO','BAJA')));
CREATE TABLE IF NOT EXISTS conductor(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,licencia VARCHAR(20) NOT NULL UNIQUE,categoria VARCHAR(12) NOT NULL,vencimiento DATE NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS asiento(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,bus_id BIGINT NOT NULL REFERENCES bus(id),numero INTEGER NOT NULL CHECK(numero>0),piso INTEGER NOT NULL CHECK(piso IN(1,2)),tipo VARCHAR(24) NOT NULL,UNIQUE(bus_id,numero));
CREATE TABLE IF NOT EXISTS viaje(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ruta_id BIGINT NOT NULL REFERENCES ruta(id),bus_id BIGINT NOT NULL REFERENCES bus(id),conductor_id BIGINT NOT NULL REFERENCES conductor(id),salida TIMESTAMP NOT NULL,precio DECIMAL(10,2) NOT NULL CHECK(precio>0),estado VARCHAR(20) NOT NULL CHECK(estado IN ('PROGRAMADO','EN_EMBARQUE','EN_RUTA','FINALIZADO','CANCELADO')));
CREATE TABLE IF NOT EXISTS promocion(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(100) NOT NULL,codigo VARCHAR(24) NOT NULL UNIQUE,tipo VARCHAR(20) NOT NULL CHECK(tipo IN ('PORCENTAJE','MONTO_FIJO')),valor DECIMAL(10,2) NOT NULL CHECK(valor>0),desde DATE NOT NULL,hasta DATE NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,CHECK(hasta>=desde));
CREATE TABLE IF NOT EXISTS cuenta_fidelizacion(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,pasajero_id BIGINT NOT NULL UNIQUE REFERENCES pasajero(id),saldo INTEGER NOT NULL DEFAULT 0 CHECK(saldo>=0),nivel VARCHAR(12) NOT NULL DEFAULT 'BASICO',fecha_alta DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS boleto(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo VARCHAR(20) NOT NULL UNIQUE,qr VARCHAR(64) NOT NULL UNIQUE,viaje_id BIGINT NOT NULL REFERENCES viaje(id),asiento_id BIGINT NOT NULL REFERENCES asiento(id),pasajero_id BIGINT NOT NULL REFERENCES pasajero(id),empleado_id BIGINT REFERENCES empleado(id),promocion_id BIGINT REFERENCES promocion(id),canal VARCHAR(15) NOT NULL CHECK(canal IN ('VENTANILLA','WEB','APP')),precio_base DECIMAL(10,2) NOT NULL,descuento DECIMAL(10,2) NOT NULL DEFAULT 0,puntos_canjeados INTEGER NOT NULL DEFAULT 0,precio_final DECIMAL(10,2) NOT NULL CHECK(precio_final>=0),estado VARCHAR(15) NOT NULL CHECK(estado IN ('EMITIDO','UTILIZADO','ANULADO')),fecha_emision TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,reprogramado_desde BIGINT REFERENCES boleto(id));
CREATE TABLE IF NOT EXISTS pago(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,boleto_id BIGINT NOT NULL UNIQUE REFERENCES boleto(id),metodo VARCHAR(24) NOT NULL,monto DECIMAL(10,2) NOT NULL CHECK(monto>=0),operacion VARCHAR(80),estado VARCHAR(20) NOT NULL CHECK(estado IN ('APROBADO','RECHAZADO','REEMBOLSADO')),fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,simulado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS movimiento_puntos(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cuenta_id BIGINT NOT NULL REFERENCES cuenta_fidelizacion(id),boleto_id BIGINT REFERENCES boleto(id),tipo VARCHAR(15) NOT NULL CHECK(tipo IN ('ACUMULA','CANJEA','DEVOLUCION')),puntos INTEGER NOT NULL CHECK(puntos>0),fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(boleto_id,tipo));
CREATE TABLE IF NOT EXISTS manifiesto(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,viaje_id BIGINT NOT NULL UNIQUE REFERENCES viaje(id),total_pasajeros INTEGER NOT NULL DEFAULT 0,estado_envio VARCHAR(20) NOT NULL CHECK(estado_envio IN ('PENDIENTE','ERROR','SIMULADO','ENVIADO')),codigo_respuesta VARCHAR(100),intentos INTEGER NOT NULL DEFAULT 0,fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS embarque(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,boleto_id BIGINT NOT NULL UNIQUE REFERENCES boleto(id),manifiesto_id BIGINT NOT NULL REFERENCES manifiesto(id),empleado_id BIGINT NOT NULL REFERENCES empleado(id),fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,estado VARCHAR(20) NOT NULL DEFAULT 'EMBARCADO');
CREATE TABLE IF NOT EXISTS usuario(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,usuario VARCHAR(50) NOT NULL UNIQUE,clave_hash VARCHAR(100) NOT NULL,rol VARCHAR(24) NOT NULL CHECK(rol IN ('ADMIN','VENDEDOR','CONTROLADOR','JEFE_OPERACIONES','PASAJERO')),empleado_id BIGINT REFERENCES empleado(id),pasajero_id BIGINT REFERENCES pasajero(id),activo BOOLEAN NOT NULL DEFAULT TRUE,intentos INTEGER NOT NULL DEFAULT 0,bloqueado_hasta TIMESTAMP,CHECK((rol='PASAJERO' AND pasajero_id IS NOT NULL) OR (rol<>'PASAJERO' AND empleado_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS reserva(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,viaje_id BIGINT NOT NULL REFERENCES viaje(id),asiento_id BIGINT NOT NULL REFERENCES asiento(id),boleto_id BIGINT REFERENCES boleto(id),token VARCHAR(64),propietario VARCHAR(50),vence TIMESTAMP,UNIQUE(viaje_id,asiento_id));
CREATE TABLE IF NOT EXISTS auditoria(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,usuario VARCHAR(50) NOT NULL,accion VARCHAR(60) NOT NULL,detalle VARCHAR(300) NOT NULL,fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evidencia_rsu(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tipo VARCHAR(30) NOT NULL,titulo VARCHAR(150) NOT NULL,descripcion VARCHAR(2000) NOT NULL,referencia VARCHAR(500),fecha DATE NOT NULL,registrado_por VARCHAR(50) NOT NULL);
CREATE INDEX IF NOT EXISTS ix_viaje_salida ON viaje(salida,ruta_id);
CREATE INDEX IF NOT EXISTS ix_boleto_pasajero ON boleto(pasajero_id);
CREATE INDEX IF NOT EXISTS ix_boleto_viaje ON boleto(viaje_id,estado);
CREATE INDEX IF NOT EXISTS ix_movimiento_cuenta ON movimiento_puntos(cuenta_id);
CREATE INDEX IF NOT EXISTS ix_embarque_manifiesto ON embarque(manifiesto_id);
